package calc

func collatz(limit int64) int64 {
	var best, bestN int64
	for n := int64(1); n < limit; n++ {
		x, steps := n, int64(0)
		for x != 1 {
			if x%2 == 0 {
				x /= 2
			} else {
				x = 3*x + 1
			}
			steps++
		}
		if steps > best {
			best, bestN = steps, n
		}
	}
	return bestN
}

package calc

import "testing"

func TestCollatz(t *testing.T) {
	if got := collatz(10); got != 9 {
		t.Errorf("collatz(10) = %d, want 9", got)
	}
	if got := collatz(100); got != 97 {
		t.Errorf("collatz(100) = %d, want 97", got)
	}
}
